// ---------------------------------------------------------------------------
// §12.1 Tables and pure functions
// ---------------------------------------------------------------------------
void TestPowerTable()
{
    std::printf("TestPowerTable\n");
    CHECK_EQ_I(kPowerTable[0], 2047);
    // Unity is the silicon 2047/2048 (not 1.0) — ymfm lineage.
    CHECK_EQ_I(VolFactor(4096, 0), 4094);
    CHECK_EQ_I(VolFactor(2048, 0), 2047);
    // Exact halving at each 6 dB multiple (shift domain).
    CHECK_EQ_I(VolFactor(4096, 64), 2047);
    CHECK_EQ_I(VolFactor(2048, 64), 1023);
    CHECK_EQ_I(VolFactor(2048, 128), 511);
    // -60 dB floor clips to silence (D5). One index above the floor the
    // full-scale remainder is a single LSB (silicon rounds it to 32).
    CHECK_EQ_I(VolFactor(32767, kMaxAttIndex), 0);
    CHECK(VolFactor(32767, kMaxAttIndex - 1) < 64);
    // Monotone non-increasing across the whole domain.
    for (uint32_t i = 0; i < kMaxAttIndex; i++)
        CHECK(VolFactor(1000, i) >= VolFactor(1000, i + 1));
}

void TestPanAndMixTables()
{
    std::printf("TestPanAndMixTables\n");
    const PanPair expected[16] = {
        {0, 0}, {32, 0}, {64, 0}, {96, 0}, {128, 0}, {160, 0}, {192, 0}, {1020, 0},
        {1020, 1020}, {0, 1020}, {0, 192}, {0, 160}, {0, 128}, {0, 96}, {0, 64}, {0, 32},
    };
    for (int i = 0; i < 16; i++)
    {
        CHECK_EQ_I(kPanTable[i].left, expected[i].left);
        CHECK_EQ_I(kPanTable[i].right, expected[i].right);
    }
    // Irregular entries: 7 left-off (hard right), 8 both-off, 9 right-off
    // (hard left) (D8). Indices 1..7 are RIGHT positions.
    CHECK_EQ_I(VolFactor(1000, kPanTable[7].left), 0);
    CHECK(kPanTable[7].right == 0);
    CHECK_EQ_I(VolFactor(1000, kPanTable[8].left), 0);
    CHECK_EQ_I(VolFactor(1000, kPanTable[8].right), 0);
    CHECK_EQ_I(VolFactor(1000, kPanTable[9].right), 0);
    CHECK(kPanTable[9].left == 0);

    // Block mix (D9): verified 11-bit mantissas.
    const int32_t mixExpected[8] = {2042, 1444, 1021, 722, 510, 361, 255, 0};
    for (int c = 0; c < 8; c++)
        CHECK_EQ_I(kMixScale[c], mixExpected[c]);
    CHECK_EQ_I(ApplyMixScale(1000, 3), 1000 * 722 / 2042);
    CHECK_EQ_I(ApplyMixScale(1000, 0), 1000 * 2042 / 2042);
    CHECK_EQ_I(ApplyMixScale(1000, 7), 0);
    // Reset decode: 0xF8 -> L code 3, R code 3 (both -9 dB).
    CHECK_EQ_I((0x1B >> 3) & 7, 3);
    CHECK_EQ_I(0x1B & 7, 3);
    CHECK_EQ_I(0x00 & 7, 0);
}

void TestRateAndStepTables()
{
    std::printf("TestRateAndStepTables\n");
    CHECK_EQ_I(kDecayLevelTable[0], 0);
    CHECK_EQ_I(kDecayLevelTable[1], 32);
    CHECK_EQ_I(kDecayLevelTable[6], 192);
    CHECK_EQ_I(kDecayLevelTable[15], 93 / 3 * 0x20); // SC(93): full silence

    CHECK_EQ_I(kEgRateShift[0], 12);
    CHECK_EQ_I(kEgRateShift[4], 11);
    CHECK_EQ_I(kEgRateShift[48], 0);
    CHECK_EQ_I(kEgRateShift[63], 0);
    CHECK_EQ_I(kEgRateSelect[0], RateRow(14));
    CHECK_EQ_I(kEgRateSelect[3], RateRow(14)); // rates 0..3 = infinity row
    for (int k = 0; k < 8; k++)
    {
        CHECK_EQ_I(kEgInc[RateRow(4) + k], 1);  // rate 13: inc 1
        CHECK_EQ_I(kEgInc[RateRow(13) + k], 8); // rate 15 attack: inc 8
        CHECK_EQ_I(kEgInc[RateRow(14) + k], 0); // infinity row unused
    }

    // calcStep (§5.3): OCT -8 freezes; base rate at fn 0 is +1024 offset.
    CHECK_EQ_I(CalcStep(-8, 1023), 0);
    CHECK_EQ_I(CalcStep(0, 0), 32768);
    CHECK_EQ_I(CalcStep(0, 1023), (2047u << 8) >> 3);
    CHECK_EQ_I(CalcStep(3, 512), (1536u << 11) >> 3);
    CHECK_EQ_I(CalcStep(-1, 0), (1024u << 7) >> 3);
    CHECK_EQ_I(CalcStep(0, 0, 128), ((1024 + 128) << 8) >> 3);
}

void TestKaiserDesigner()
{
    std::printf("TestKaiserDesigner\n");
    // Reference values generated by an independent Python implementation of
    // the same formula (BesselI0 series + sinc + DC normalisation).
    const std::vector<double> h = DesignKaiser(96, 20000.0, 44100.0, 5.0);
    CHECK_EQ_I(h.size(), 96u);
    CHECK_EQ_F(h[0], -6.4096278644817185e-05);
    CHECK_EQ_F(h[47], 0.62970011073945353);
    CHECK_EQ_F(h[48], 0.62970011073945353);
    CHECK_EQ_F(h[95], -6.4096278644817185e-05);
    double sum = 0.0;
    for (double x : h)
        sum += x;
    CHECK_EQ_F(sum, 1.0); // unity DC gain
    for (int i = 0; i < 96; i++)
        CHECK(h[i] == h[95 - i]); // bit-exact symmetry
}

// ---------------------------------------------------------------------------
// Tone header fetch (D7) and memory access (MA)
// ---------------------------------------------------------------------------
void TestHeaderDecode()
{
    std::printf("TestHeaderDecode\n");
    // Small ROM so a wave-table header slot lands in writable SRAM: wave 342
    // fetches from 342*12 = 4104, just past the 4 KiB ROM window.
    TestChip tc(0x1000, 0x400000 - 0x1000);
    const uint8_t banks[5] = {0x11, 0x22, 0x33, 0x44, 0x55};
    WriteToneHeader(tc.mem, 342 * 12, 2, kSmpBase, 0x1234, 0x0456, banks);

    tc.chip.WriteWave(1000, 0x20, 0x01); // slot 0 wave bit 9 (wave = 0x100+)
    tc.chip.WriteWave(1000, 0x08, 0x56); // wave low: wave = 342 -> fetch

    const PcmSlot& s = tc.chip.PcmForTest().Slots()[0];
    CHECK_EQ_I(s.wave, 342);
    CHECK_EQ_I(s.bits, 2);
    CHECK_EQ_I(s.startAddr, kSmpBase);
    CHECK_EQ_I(s.loopAddr, 0x1234);
    CHECK_EQ_I(s.endAddr, 0x10000 - 0x0456); // stored complement (chip form)
    // Bytes 7..11 rewrote banks 5..9 observably (reg = 0x08 + slot + 24*bank).
    for (int b = 0; b < 5; b++)
        CHECK_EQ_I(tc.chip.PcmForTest().PeekReg(static_cast<uint8_t>(0x08 + (b + 5) * 24)),
                   banks[b]);

    // LD window: 9600 master clocks after the fetch (§3.3). LD reads on
    // status bit 1, BUSY on bit 0 (openMSX YMF278B::readYMF278Status).
    CHECK((tc.chip.ReadStatus(1000 + 9599) & 0x02) != 0);
    CHECK((tc.chip.ReadStatus(1000 + 9599) & 0x01) != 0);
    CHECK((tc.chip.ReadStatus(1000 + 9600) & 0x02) == 0);
    CHECK((tc.chip.ReadStatus(1000 + 9600) & 0x01) == 0);
}

void TestHeaderDecodeHighWave()
{
    std::printf("TestHeaderDecodeHighWave\n");
    // Small ROM so 0x80000 (headerBase 1) lands in SRAM and is writable.
    TestChip tc(0x1000, 0x400000 - 0x1000);
    const uint8_t banks[5] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE};
    WriteToneHeader(tc.mem, 0x80000, 0, 0x200100, 0x0001, 0x0002, banks);

    tc.chip.WriteWave(1000, 0x02, 0x04); // headerBase = 1, MA = 0
    tc.chip.WriteWave(1000, 0x20, 0x01); // slot 0 wave bit 9 (bank 1 bit 0)
    tc.chip.WriteWave(1000, 0x08, 0x80); // wave low: wave = 384 -> fetch at 0x80000

    const PcmSlot& s = tc.chip.PcmForTest().Slots()[0];
    CHECK_EQ_I(s.wave, 384);
    CHECK_EQ_I(s.bits, 0);
    CHECK_EQ_I(s.startAddr, 0x200100);
    CHECK_EQ_I(tc.chip.PcmForTest().PeekReg(0x80), 0xAA); // bank 5 = 0x08+5*24 rewritten
}

void TestMemoryAccess()
{
    std::printf("TestMemoryAccess\n");
    TestChip tc;

    // MA = 0 (reset): port 6 writes ignored, reads 0xFF, no auto-increment.
    tc.chip.WriteWave(1000, 0x06, 0x5A);
    CHECK_EQ_I(tc.chip.ReadWave(1000, 0x06), 0xFF);
    CHECK_EQ_I(tc.chip.PcmForTest().MemAdr(), 0u);
    CHECK(tc.mem.Read(0x200000) == 0x00); // SRAM untouched

    // MA = 1: direct access with latch-commit on reg 5.
    tc.chip.WriteWave(2000, 0x02, 0x01);
    tc.chip.WriteWave(2000, 0x03, 0x20); // latch only (upper bits masked)
    tc.chip.WriteWave(2000, 0x04, 0x00);
    CHECK_EQ_I(tc.chip.PcmForTest().MemAdr(), 0u); // not committed yet
    tc.chip.WriteWave(2000, 0x05, 0x00);           // commit 0x200000
    CHECK_EQ_I(tc.chip.PcmForTest().MemAdr(), 0x200000u);

    tc.chip.WriteWave(2000, 0x06, 0x5A); // write + auto-increment
    tc.chip.WriteWave(2000, 0x06, 0xA5);
    CHECK_EQ_I(tc.chip.PcmForTest().MemAdr(), 0x200002u);

    tc.chip.WriteWave(2000, 0x03, 0x20);
    tc.chip.WriteWave(2000, 0x04, 0x00);
    tc.chip.WriteWave(2000, 0x05, 0x00); // back to 0x200000
    CHECK_EQ_I(tc.chip.ReadWave(2000, 0x06), 0x5A);
    CHECK_EQ_I(tc.chip.ReadWave(2000, 0x06), 0xA5);

    // Dirty bitmap over the whole write burst.
    size_t bytes = 0;
    const uint8_t* bmp = tc.chip.RamDirtyBitmap(&bytes);
    CHECK(bmp != nullptr);
    CHECK_EQ_I(bytes, 1024u);
    CHECK(bmp[0x200000 / WaveMemory::kDirtyPageSize] == 1);
    CHECK(tc.mem.DirtyPageCount() > 0);
    tc.chip.ClearRamDirty();
    CHECK(tc.mem.DirtyPageCount() == 0);
}

// ---------------------------------------------------------------------------
// TL interpolation cadence (D6) and reducer cadence (§4.3)
// ---------------------------------------------------------------------------
void TestTlInterpolation()
{
    std::printf("TestTlInterpolation\n");
    TestChip tc;
    tc.chip.WriteWave(0, 0x50, 0x03); // TL 1, LD 1: immediate
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 1);
    tc.chip.WriteWave(0, 0x50, 0x7E); // TL dest 0x3F, LD 0: interpolate
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 1); // unchanged immediately

    // Down-cadence: exactly one step per 27 output samples (egCnt phase 0).
    // Run() takes absolute timestamps — track t explicitly.
    uint64_t t = 0;
    t += 27 * kOutClocks;
    tc.chip.Run(t);
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 2);
    t += 27 * kOutClocks;
    tc.chip.Run(t);
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 3);
    t += 243 * kOutClocks;
    tc.chip.Run(t); // 9 more steps
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 12);
    t += 27 * 51 * kOutClocks;
    tc.chip.Run(t); // 51 more steps: saturate at dest
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 0x3F);

    // Brighten direction moves twice as fast (13.5-sample cadence).
    tc.chip.WriteWave(t, 0x50, 0x02); // dest 1, LD 0
    t += 27 * kOutClocks;
    tc.chip.Run(t);
    const int tlAfter = tc.chip.PcmForTest().Slots()[0].tl;
    CHECK(tlAfter < 0x3F); // moving down
    t += 27 * 40 * kOutClocks;
    tc.chip.Run(t);
    CHECK_EQ_I(tc.chip.PcmForTest().Slots()[0].tl, 1);
}

void TestReducerCadence()
{
    std::printf("TestReducerCadence\n");
    TestChip tc;
    // 57 output windows of 768 clocks contain exactly 64 FM ticks (768/684 =
    // 64/57): 7 FM samples dropped per 57 — the HoldDrop ratio (§4.3).
    uint64_t t = 57 * kOutClocks;
    tc.chip.Run(t);
    CHECK_EQ_I(tc.chip.DebugOutSteps(), 57u);
    CHECK_EQ_I(tc.chip.DebugFmTicks(), 64u);
    t += 57 * kOutClocks; // twice through: no drift
    tc.chip.Run(t);
    CHECK_EQ_I(tc.chip.DebugOutSteps(), 114u);
    CHECK_EQ_I(tc.chip.DebugFmTicks(), 128u);

    // Grid positions are exact floor functions of the master position.
    for (int k = 0; k < 30; k++)
    {
        t += 137;
        tc.chip.Run(t);
        CHECK_EQ_I(tc.chip.DebugOutSteps(), t / kOutDivider);
        CHECK_EQ_I(tc.chip.DebugFmTicks(), t / kFmDivider);
    }
}

// ---------------------------------------------------------------------------
// Bus timing (§3.3)
// ---------------------------------------------------------------------------
void TestBusTiming()
{
    std::printf("TestBusTiming\n");
    TestChip tc;

    // FM write: 56 master clocks of BUSY.
    tc.chip.WriteFm(1000, 0, 0x20, 0x01);
    CHECK((tc.chip.ReadStatus(1055) & 0x01) != 0);
    CHECK((tc.chip.ReadStatus(1056) & 0x01) == 0);

    // Wave register write: 88 clocks.
    tc.chip.WriteFm(2000, 0, 0x21, 0x01);      // unrelated FM write first
    tc.chip.WriteWave(5000, 0x50, 0x02);
    CHECK((tc.chip.ReadStatus(5087) & 0x01) != 0);
    CHECK((tc.chip.ReadStatus(5088) & 0x01) == 0);
    CHECK((tc.chip.ReadStatus(5088) & 0x02) == 0); // no LD on a plain reg write

    // Memory-path write (0x05): 28 clocks of BUSY and no LD window -
    // LD opens only on tone-load writes to regs 0x08..0x1F (openMSX
    // YMF278B::writeIO gates LOAD_DELAY on exactly that range).
    tc.chip.WriteWave(10000, 0x05, 0x00);
    CHECK((tc.chip.ReadStatus(10027) & 0x01) != 0);
    CHECK((tc.chip.ReadStatus(10028) & 0x01) == 0);
    CHECK((tc.chip.ReadStatus(10028) & 0x02) == 0);

    // Memory read (0x06): 38 clocks (no MA -> no access, no LD).
    tc.chip.ReadWave(20000, 0x06);
    CHECK((tc.chip.ReadStatus(20037) & 0x01) != 0);
    CHECK((tc.chip.ReadStatus(20038) & 0x01) == 0);
}

// ---------------------------------------------------------------------------
// Unity bypass (R6) and render stream rates
// ---------------------------------------------------------------------------
void TestUnityBypass()
{
    std::printf("TestUnityBypass\n");
    Opl4Render r;
    Opl4Config cfg; // Authentic, 44100
    r.Configure(cfg);
    CHECK(r.UnityBypass());

    // Wide rail values: ±131072 is full scale, normalized to ±1.0f.
    const int32_t in[6] = {-131072, 131072, -1, 1, 0, 100};
    float out[6] = {};
    size_t consumed = 0;
    CHECK_EQ_I(r.ProcessChip(in, 3, out, 3, &consumed), 3u);
    CHECK_EQ_I(consumed, 3u);
    // Normalization: value / 131072.0f
    constexpr float kNormScale = 1.0f / 131072.0f;
    for (int i = 0; i < 6; i++)
        CHECK(out[i] == static_cast<float>(in[i]) * kNormScale);

    r.SetBoardAnalog(true);
    CHECK(!r.UnityBypass());
    r.SetBoardAnalog(false);
    CHECK(r.UnityBypass());
}

void TestStreamRate()
{
    std::printf("TestStreamRate\n");
    // 44100 out: one frame per chip frame, exactly.
    {
        TestChip tc(2u << 20, 1u << 20);
        tc.chip.Run(44100 * kOutClocks);
        std::vector<float> out(65536 * 2);
        CHECK_EQ_I(tc.chip.Render(out.data(), 65536), 44100u);
    }
    // 48000 out: resampled ratio within 0.1%.
    {
        TestChip tc(2u << 20, 1u << 20, 48000);
        tc.chip.Run(44100 * kOutClocks);
        std::vector<float> out(65536 * 2);
        const size_t n = tc.chip.Render(out.data(), 65536);
        CHECK(n > 47952 && n < 48048);
    }
}

// ---------------------------------------------------------------------------
// Determinism (§9) — interleaved vs batched pull, twin-chip replay
// ---------------------------------------------------------------------------
void TestDeterminism()
{
    std::printf("TestDeterminism\n");
    const auto script = [](TestChip& tc, uint64_t t)
    {
        KeyOnFmCh0(tc.chip, t);
        KeyOnPcmSlot(tc.chip, 0, t);
    };

    TestChip a;
    WriteToneHeader(a.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(a.mem);
    script(a, 1000);

    TestChip b;
    WriteToneHeader(b.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(b.mem);
    script(b, 1000);

    std::vector<float> outA, outB;
    outA.reserve(131072);
    outB.reserve(131072);
    float buf[16384];

    // A: per-frame pull (host-like cadence). B: one batch pull at the end.
    uint64_t t = 1000;
    for (int f = 0; f < 32; f++)
    {
        t += 735 * kOutClocks;
        a.chip.Run(t);
        size_t n;
        while ((n = a.chip.Render(buf, 8192)) > 0)
            outA.insert(outA.end(), buf, buf + n * 2);
    }
    b.chip.Run(t);
    size_t n;
    while ((n = b.chip.Render(buf, 8192)) > 0)
        outB.insert(outB.end(), buf, buf + n * 2);

    CHECK_EQ_I(outA.size(), outB.size());
    CHECK(outA.size() == outB.size()
          && std::equal(outA.begin(), outA.end(), outB.begin())); // bit-identical

    // The stream is non-silent in both engines (script sanity).
    // Normalized scale: compare against 1000 / 131072 ≈ 0.0076.
    float maxAbs = 0.0f;
    for (float v : outA)
        maxAbs = std::max(maxAbs, std::fabs(v));
    CHECK(maxAbs > 1000.0f * kNormScale);
}

void TestSaveRestore()
{
    std::printf("TestSaveRestore\n");
    const uint64_t t1 = 2000 * kOutClocks;
    const uint64_t t2 = 5000 * kOutClocks;
    std::vector<uint8_t> state;

    TestChip a;
    WriteToneHeader(a.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(a.mem);
    KeyOnFmCh0(a.chip, 1000);
    KeyOnPcmSlot(a.chip, 0, 1000);
    a.chip.Run(t1);
    float sink[16384];
    while (a.chip.Render(sink, 8192) > 0)
    {
    }

    const size_t stateSize = a.chip.StateSize();
    state.resize(stateSize);
    a.chip.SaveState(state.data());
    CHECK_EQ_I(a.chip.StateSize(), stateSize); // stable across saves

    // A continues: key off FM, key a second PCM slot.
    a.chip.WriteFm(t1, 0, 0xB0, 0x10);
    KeyOnPcmSlot(a.chip, 1, t1);
    a.chip.Run(t2);
    std::vector<float> outA;
    float buf[16384];
    size_t n;
    while ((n = a.chip.Render(buf, 8192)) > 0)
        outA.insert(outA.end(), buf, buf + n * 2);

    // B: fresh chip with identical memory, restore, same continuation.
    TestChip b;
    WriteToneHeader(b.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(b.mem);
    b.chip.LoadState(state.data());
    CHECK_EQ_I(b.chip.DebugOutSteps(), 2000u); // clocks restored to t1
    b.chip.WriteFm(t1, 0, 0xB0, 0x10);
    KeyOnPcmSlot(b.chip, 1, t1);
    b.chip.Run(t2);
    std::vector<float> outB;
    while ((n = b.chip.Render(buf, 8192)) > 0)
        outB.insert(outB.end(), buf, buf + n * 2);

    CHECK_EQ_I(outA.size(), outB.size());
    CHECK(outA.size() == outB.size()
          && std::equal(outA.begin(), outA.end(), outB.begin())); // exact restore

    // Save is side-effect free (§9.2 item 1): a mid-run SaveState must not
    // alter the rendered stream.
    TestChip c, d;
    for (TestChip* tc : {&c, &d})
    {
        WriteToneHeader(tc->mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
        WriteMaxSampleData(tc->mem);
        KeyOnFmCh0(tc->chip, 1000);
        KeyOnPcmSlot(tc->chip, 0, 1000);
    }
    std::vector<uint8_t> scratch(c.chip.StateSize());
    c.chip.Run(t1);
    c.chip.SaveState(scratch.data()); // <-- the only difference
    c.chip.Run(t2);
    d.chip.Run(t2);
    std::vector<float> outC, outD;
    while ((n = c.chip.Render(buf, 8192)) > 0)
        outC.insert(outC.end(), buf, buf + n * 2);
    while ((n = d.chip.Render(buf, 8192)) > 0)
        outD.insert(outD.end(), buf, buf + n * 2);
    CHECK_EQ_I(outC.size(), outD.size());
    CHECK(outC.size() == outD.size()
          && std::equal(outC.begin(), outC.end(), outD.begin()));
}

// ---------------------------------------------------------------------------
// Block mix (D9) and output clip (D10)
// ---------------------------------------------------------------------------
void TestBlockMixAndClip()
{
    std::printf("TestBlockMixAndClip\n");
    const auto renderAll = [](TestChip& tc, uint64_t until, std::vector<float>& out)
    {
        tc.chip.Run(until);
        float buf[16384];
        size_t n;
        out.clear();
        while ((n = tc.chip.Render(buf, 8192)) > 0)
            out.insert(out.end(), buf, buf + n * 2);
    };
    const auto maxCh = [](const std::vector<float>& v, int ch)
    {
        float m = 0.0f;
        for (size_t i = 0; i < v.size() / 2; i++)
            m = std::max(m, std::fabs(v[i * 2 + ch]));
        return m;
    };

    // Two max-amplitude PCM slots at unity mix sum without clipping (wide rail
    // gives 4 voices headroom). Expected: 2*32767 normalized ≈ 0.5.
    {
        TestChip tc;
        WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
        WriteMaxSampleData(tc.mem);
        KeyOnPcmSlot(tc.chip, 0, 1000);
        KeyOnPcmSlot(tc.chip, 1, 1000);
        std::vector<float> out;
        renderAll(tc, 1500 * kOutClocks, out);
        // 2 * 32767 / 131072 ≈ 0.5 (no clipping at wide rail)
        CHECK(maxCh(out, 0) > 0.49f && maxCh(out, 0) < 0.51f);
        CHECK(maxCh(out, 1) > 0.49f && maxCh(out, 1) < 0.51f);
    }

    // 0xF8 = 0xFF (FM -inf both sides): an keyed FM voice contributes nothing.
    std::vector<float> withFmMuted, pcmOnly;
    {
        TestChip tc;
        WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
        WriteMaxSampleData(tc.mem);
        KeyOnPcmSlot(tc.chip, 0, 1000);
        KeyOnFmCh0(tc.chip, 1000);
        tc.chip.WriteWave(1000, 0xF8, 0xFF); // L 7 / R 7: FM muted
        renderAll(tc, 1500 * kOutClocks, withFmMuted);
    }
    {
        TestChip tc;
        WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
        WriteMaxSampleData(tc.mem);
        KeyOnPcmSlot(tc.chip, 0, 1000);
        renderAll(tc, 1500 * kOutClocks, pcmOnly);
    }
    CHECK_EQ_I(withFmMuted.size(), pcmOnly.size());
    CHECK(withFmMuted.size() == pcmOnly.size()
          && std::equal(withFmMuted.begin(), withFmMuted.end(), pcmOnly.begin()));

    // 0xF8 = 0x38 (L muted, R unity): FM appears on the right only.
    std::vector<float> asym;
    {
        TestChip tc;
        WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
        WriteMaxSampleData(tc.mem);
        KeyOnPcmSlot(tc.chip, 0, 1000);
        KeyOnFmCh0(tc.chip, 1000);
        tc.chip.WriteWave(1000, 0xF8, 0x38);
        renderAll(tc, 1500 * kOutClocks, asym);
    }
    CHECK_EQ_F(maxCh(asym, 0), maxCh(pcmOnly, 0)); // left = PCM only
    CHECK(maxCh(asym, 1) > maxCh(pcmOnly, 1));     // right = PCM + FM
}

// ---------------------------------------------------------------------------
// Pan routing through the whole chip (D8 end-to-end)
// ---------------------------------------------------------------------------
void TestPanRouting()
{
    std::printf("TestPanRouting\n");
    struct Peaks
    {
        float l;
        float r;
    };
    // Runs and renders in ONE pass — the drain is destructive, so a
    // per-channel query would see an empty stream the second time.
    const auto peaks = [](TestChip& tc)
    {
        tc.chip.Run(1500 * kOutClocks);
        float buf[16384];
        Peaks p = {0.0f, 0.0f};
        size_t n;
        while ((n = tc.chip.Render(buf, 8192)) > 0)
            for (size_t i = 0; i < n; i++)
            {
                p.l = std::max(p.l, std::fabs(buf[i * 2]));
                p.r = std::max(p.r, std::fabs(buf[i * 2 + 1]));
            }
        return p;
    };

    TestChip right;
    WriteToneHeader(right.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(right.mem);
    KeyOnPcmSlot(right.chip, 0, 1000, 7); // pan 7: hard right, left off
    const Peaks pr = peaks(right);
    CHECK(pr.l < 1.0f * kNormScale);
    CHECK(pr.r > 20000.0f * kNormScale);

    // Pan 1 is one step right of centre: right full, left -3 dB (D8).
    TestChip soft;
    WriteToneHeader(soft.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(soft.mem);
    KeyOnPcmSlot(soft.chip, 0, 1000, 1);
    const Peaks ps = peaks(soft);
    CHECK(ps.r > 20000.0f * kNormScale);
    CHECK(ps.l > ps.r * 0.70f && ps.l < ps.r * 0.72f);

    TestChip off;
    WriteToneHeader(off.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(off.mem);
    KeyOnPcmSlot(off.chip, 0, 1000, 8); // pan 8: both off
    float buf[16384];
    off.chip.Run(1500 * kOutClocks);
    const size_t n = off.chip.Render(buf, 8192);
    float m = 0.0f;
    for (size_t i = 0; i < n * 2; i++)
        m = std::max(m, std::fabs(buf[i]));
    CHECK_EQ_F(m, 0.0);
}

// ---------------------------------------------------------------------------
// Channel taps: mute and peaks (R7)
// ---------------------------------------------------------------------------
void TestTaps()
{
    std::printf("TestTaps\n");
    TestChip tc;
    WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(tc.mem);
    KeyOnFmCh0(tc.chip, 1000);
    KeyOnPcmSlot(tc.chip, 0, 1000);
    tc.chip.Run(1100 * kOutClocks);

    CHECK_EQ_I(tc.chip.ChannelCount(ChannelGroup::Fm), 18u);
    CHECK_EQ_I(tc.chip.ChannelCount(ChannelGroup::Pcm), 24u);
    CHECK(tc.chip.ChannelPeak({ChannelGroup::Fm, 0}) > 0.0f);
    CHECK(tc.chip.ChannelPeak({ChannelGroup::Pcm, 0}) > 0.0f);
    CHECK_EQ_F(tc.chip.ChannelPeak({ChannelGroup::Fm, 17}), 0.0);
    CHECK_EQ_F(tc.chip.ChannelPeak({ChannelGroup::Pcm, 23}), 0.0);

    // Muting PCM slot 0 removes its contribution exactly: the post-mute
    // stream equals an FM-only render. (FM alone at TL 0 reaches near full
    // scale, so an absolute threshold cannot separate the engines.)
    TestChip fmOnly;
    KeyOnFmCh0(fmOnly.chip, 1000);
    fmOnly.chip.Run(1100 * kOutClocks);
    float drain[16384];
    while (fmOnly.chip.Render(drain, 8192) > 0)
    {
    }
    fmOnly.chip.Run(2000 * kOutClocks);
    float refMax = 0.0f;
    size_t rn;
    while ((rn = fmOnly.chip.Render(drain, 8192)) > 0)
        for (size_t i = 0; i < rn * 2; i++)
            refMax = std::max(refMax, std::fabs(drain[i]));
    CHECK(refMax > 0.0f);

    while (tc.chip.Render(drain, 8192) > 0) // drop the pre-mute mix
    {
    }
    const auto fmTapBefore = tc.chip.ChannelPeak({ChannelGroup::Fm, 0});
    tc.chip.SetChannelMute({ChannelGroup::Pcm, 0}, true);
    float buf[16384];
    float maxAbs = 0.0f;
    size_t n;
    tc.chip.Run(2000 * kOutClocks);
    while ((n = tc.chip.Render(buf, 8192)) > 0)
        for (size_t i = 0; i < n * 2; i++)
            maxAbs = std::max(maxAbs, std::fabs(buf[i]));
    CHECK(maxAbs > 0.0f);        // FM still audible
    CHECK_EQ_F(maxAbs, refMax);  // PCM contribution removed exactly
    CHECK(tc.chip.ChannelPeak({ChannelGroup::Fm, 0}) >= fmTapBefore * 0.5f);
    tc.chip.SetChannelMute({ChannelGroup::Pcm, 0}, false);
}

// ---------------------------------------------------------------------------
// HiFi at the native 44100 output (regression): Configure used to skip the
// split resamplers when output == chip rate, so ProcessSplit read an
// unconfigured resampler. Must render with sane lengths, not crash.
// ---------------------------------------------------------------------------
void TestHiFiAt44100()
{
    std::printf("TestHiFiAt44100\n");
    TestChip tc(2u << 20, 1u << 20, 44100);
    tc.cfg.mode = RenderMode::HiFi;
    tc.chip.Configure(tc.cfg, &tc.mem);
    tc.chip.Reset(0);

    WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(tc.mem);
    KeyOnFmCh0(tc.chip, 1000);
    KeyOnPcmSlot(tc.chip, 0, 1000);

    tc.chip.Run(2000 * kOutClocks);
    float buf[16384];
    size_t total = 0, n;
    float maxAbs = 0.0f;
    while ((n = tc.chip.Render(buf, 8192)) > 0)
    {
        total += n;
        for (size_t i = 0; i < n * 2; i++)
            maxAbs = std::max(maxAbs, std::fabs(buf[i]));
    }
    CHECK(total > 1900 && total < 2100); // ~2000 output frames
    CHECK(maxAbs > 0.0f);                // audio actually flowed
}

// ---------------------------------------------------------------------------
// Split render (host mixer sources, integration D5): FM-only and PCM-only
// streams whose integer sum equals the mixed stream wherever the 16-bit
// sum does not saturate; resampled rates keep the ratio; turbo discard.
// ---------------------------------------------------------------------------
void TestRenderSplit()
{
    std::printf("TestRenderSplit\n");

    // Mixed vs split consistency at the 44100 bypass.
    TestChip a;
    WriteToneHeader(a.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(a.mem);
    KeyOnFmCh0(a.chip, 1000);
    KeyOnPcmSlot(a.chip, 0, 1000);
    a.chip.Run(2000 * kOutClocks);

    TestChip b;
    WriteToneHeader(b.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(b.mem);
    b.chip.EnableSplitStreams(true);
    CHECK(b.chip.SplitStreamsEnabled());
    KeyOnFmCh0(b.chip, 1000);
    KeyOnPcmSlot(b.chip, 0, 1000);
    b.chip.Run(2000 * kOutClocks);

    float mixed[16384];
    float fm[16384];
    float pcm[16384];
    const size_t mixedN = a.chip.Render(mixed, 8192);
    const size_t splitN = b.chip.RenderSplit(fm, pcm, 8192);
    CHECK_EQ_I(mixedN, 2000u);
    CHECK_EQ_I(splitN, 2000u);

    // Both groups are live on their own.
    float fmMax = 0.0f, pcmMax = 0.0f;
    for (size_t i = 0; i < splitN * 2; i++)
    {
        fmMax = std::max(fmMax, std::fabs(fm[i]));
        pcmMax = std::max(pcmMax, std::fabs(pcm[i]));
    }
    CHECK(fmMax > 1000.0f * kNormScale);
    CHECK(pcmMax > 1000.0f * kNormScale);

    // Where the integer sum did not saturate, fm + pcm == mixed exactly
    // (all three carry the normalized int32 values through the bypass path).
    size_t compared = 0;
    for (size_t i = 0; i < mixedN * 2; i++)
    {
        if (std::fabs(mixed[i]) < 32000.0f * kNormScale)
        {
            if (!(static_cast<double>(fm[i]) + static_cast<double>(pcm[i])
                  == static_cast<double>(mixed[i])))
            {
                CHECK(false);
                break;
            }
            compared++;
        }
    }
    CHECK(compared > 1000); // mostly below the saturation threshold

    // Split at 48 kHz: ratio kept, both sources carry audio.
    TestChip tc48(2u << 20, 1u << 20, 48000);
    WriteToneHeader(tc48.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(tc48.mem);
    tc48.chip.EnableSplitStreams(true);
    KeyOnFmCh0(tc48.chip, 1000);
    KeyOnPcmSlot(tc48.chip, 0, 1000);
    tc48.chip.Run(2000 * kOutClocks);
    const size_t n48 = tc48.chip.RenderSplit(fm, pcm, 16384 / 2);
    CHECK(n48 > 2100 && n48 < 2250); // ~2000 * 48/44.1 = 2177
    float fm48 = 0.0f, pcm48 = 0.0f;
    for (size_t i = 0; i < n48 * 2; i++)
    {
        fm48 = std::max(fm48, std::fabs(fm[i]));
        pcm48 = std::max(pcm48, std::fabs(pcm[i]));
    }
    CHECK(fm48 > 500.0f * kNormScale);
    CHECK(pcm48 > 500.0f * kNormScale);
}

void TestDiscardPendingAudio()
{
    std::printf("TestDiscardPendingAudio\n");
    TestChip tc;
    WriteToneHeader(tc.mem, kHdrBase, 2, kSmpBase, 0, 4, nullptr);
    WriteMaxSampleData(tc.mem);
    KeyOnPcmSlot(tc.chip, 0, 1000);
    tc.chip.Run(1000 * kOutClocks);

    // Turbo host: drop the buffered audio, keep running the core.
    tc.chip.DiscardPendingAudio();
    tc.chip.WriteWave(1000 * kOutClocks + 8, static_cast<uint8_t>(0x08 + 24 * 4), 0x00); // key off
    tc.chip.Run(2000 * kOutClocks);

    float buf[16384];
    const size_t n = tc.chip.Render(buf, 8192);
    CHECK_EQ_I(n, 1000u); // only the post-discard frames arrive
}

// ---------------------------------------------------------------------------
// Output-stage purity (2026-09-18-2045-opl4-output-stage-harshness.md).
// THD+N by least-squares fit of DC + sine + cosine at the known pitch: the
// residual is everything that is not the tone.
// ---------------------------------------------------------------------------
double ThdNdB(const std::vector<float>& x, size_t from, double f0, double fs)
{
    double s11 = 0, s12 = 0, s13 = 0, s22 = 0, s23 = 0, s33 = 0, y1 = 0, y2 = 0, y3 = 0;
    const size_t n = x.size();
    for (size_t i = from; i < n; i++)
    {
        const double w = 2.0 * M_PI * f0 * static_cast<double>(i) / fs;
        const double a = 1.0, b = std::sin(w), c = std::cos(w), y = x[i];
        s11 += a * a; s12 += a * b; s13 += a * c; s22 += b * b; s23 += b * c; s33 += c * c;
        y1 += a * y; y2 += b * y; y3 += c * y;
    }
    // Solve the 3x3 normal equations (Cramer).
    const double det = s11 * (s22 * s33 - s23 * s23) - s12 * (s12 * s33 - s23 * s13) + s13 * (s12 * s23 - s22 * s13);
    const double k0 = (y1 * (s22 * s33 - s23 * s23) - s12 * (y2 * s33 - s23 * y3) + s13 * (y2 * s23 - s22 * y3)) / det;
    const double k1 = (s11 * (y2 * s33 - s23 * y3) - y1 * (s12 * s33 - s23 * s13) + s13 * (s12 * y3 - y2 * s13)) / det;
    const double k2 = (s11 * (s22 * y3 - y2 * s23) - s12 * (s12 * y3 - y2 * s13) + y1 * (s12 * s23 - s22 * s13)) / det;
    double fit = 0, res = 0;
    for (size_t i = from; i < n; i++)
    {
        const double w = 2.0 * M_PI * f0 * static_cast<double>(i) / fs;
        const double t = k1 * std::sin(w) + k2 * std::cos(w);
        const double e = x[i] - k0 - t;
        fit += t * t;
        res += e * e;
    }
    return 10.0 * std::log10(res / fit);
}

void TestResamplerPurityAndDirection()
{
    std::printf("TestResamplerPurityAndDirection\n");
    const double fmRate = static_cast<double>(kMasterClockHz) / static_cast<double>(kFmDivider);
    PolyphaseResampler r;
    r.Configure(fmRate, 44100.0, Quality::Reference);
    std::vector<float> out;
    float frame[24];
    for (size_t i = 0; i < 60000; i++)
    {
        const float v = 0.5f * static_cast<float>(std::sin(2.0 * M_PI * 4231.1 * static_cast<double>(i) / fmRate));
        const size_t n = r.Process(v, v, frame);
        for (size_t j = 0; j < n; j++)
            out.push_back(frame[j * 2]);
    }
    const double thd = ThdNdB(out, 400, 4231.1, 44100.0);
    std::printf("  4.23 kHz sine 49516.4 -> 44100: THD+N %.1f dB\n", thd);
    CHECK(thd < -60.0); // the old blended-FIR scheme measured -10 dB here

    // Output time must advance with the phase: a slow ramp stays monotonic.
    PolyphaseResampler ramp;
    ramp.Configure(fmRate, 44100.0, Quality::Reference);
    std::vector<float> rout;
    for (size_t i = 0; i < 4000; i++)
    {
        const float v = static_cast<float>(i) * 1e-4f;
        const size_t n = ramp.Process(v, v, frame);
        for (size_t j = 0; j < n; j++)
            rout.push_back(frame[j * 2]);
    }
    int backwards = 0;
    for (size_t i = 200; i + 1 < rout.size(); i++)
        if (rout[i + 1] <= rout[i])
            backwards++;
    CHECK_EQ_I(backwards, 0);
}

std::vector<float> RenderFmSine(RenderMode mode, bool board, bool mixed, int fnum, int blk,
                                bool boardBeforeModeChange = false)
{
    TestChip tc(2u << 20, 1u << 20, 44100);
    if (boardBeforeModeChange)
    {
        // Settings applied first must survive the mode/quality reconfigure.
        tc.chip.SetBoardAnalog(board);
        tc.chip.SetRenderMode(mode);
        tc.chip.SetQuality(Quality::HighFidelity);
        tc.chip.EnableSplitStreams(!mixed);
    }
    else
    {
        tc.cfg.mode = mode;
        tc.chip.Configure(tc.cfg, &tc.mem);
        tc.chip.EnableSplitStreams(!mixed);
        tc.chip.Reset(0);
        tc.chip.SetBoardAnalog(board);
    }
    uint64_t t = 10;
    tc.chip.WriteFm(t, 1, 0x05, 0x01);
    const uint8_t w[][2] = {{0x20, 0x21}, {0x23, 0x21}, {0x40, 0x3F}, {0x43, 0x00}, {0x60, 0xF0},
                            {0x63, 0xF0}, {0x80, 0x00}, {0x83, 0x00}, {0xC0, 0x31}};
    for (const auto& x : w)
        tc.chip.WriteFm(t += 10, 0, x[0], x[1]);
    tc.chip.WriteFm(t += 10, 0, 0xA0, static_cast<uint8_t>(fnum & 0xFF));
    tc.chip.WriteFm(t += 10, 0, 0xB0, static_cast<uint8_t>(0x20 | (blk << 2) | (fnum >> 8)));
    std::vector<float> mono;
    std::vector<float> fm(2 * 1024), pcm(2 * 1024);
    for (int frame = 1; frame <= 100; frame++)
    {
        tc.chip.Run(static_cast<uint64_t>(frame) * 882 * kOutClocks);
        const size_t n = mixed ? tc.chip.Render(fm.data(), 882) : tc.chip.RenderSplit(fm.data(), pcm.data(), 882);
        for (size_t i = 0; i < n; i++)
            mono.push_back(0.5f * (fm[i * 2] + fm[i * 2 + 1]));
    }
    return mono;
}

double RmsFrom(const std::vector<float>& v, size_t from)
{
    double acc = 0;
    for (size_t i = from; i < v.size(); i++)
        acc += static_cast<double>(v[i]) * v[i];
    return std::sqrt(acc / static_cast<double>(v.size() - from));
}

void TestChipSinePurityPerMode()
{
    std::printf("TestChipSinePurityPerMode\n");
    const double f0 = 700.0 * 128.0 * (static_cast<double>(kMasterClockHz) / kFmDivider) / 1048576.0;
    for (bool mixed : {false, true})
    {
        const auto hifi = RenderFmSine(RenderMode::HiFi, false, mixed, 700, 7);
        const auto auth = RenderFmSine(RenderMode::Authentic, false, mixed, 700, 7);
        const double tH = ThdNdB(hifi, 4410, f0, 44100.0), tA = ThdNdB(auth, 4410, f0, 44100.0);
        std::printf("  %s 4.23 kHz FM sine: HiFi THD+N %.1f dB (%zu frames), Authentic %.1f dB (HoldDrop jitter)\n",
                    mixed ? "Render()     " : "RenderSplit()", tH, hifi.size(), tA);
        CHECK(hifi.size() == 88200);  // 100 frames x 882: no stalled or runaway staging
        CHECK(tH < -45.0);            // was -9.8 dB with the blended FIR
        CHECK(tA < -12.0 && tA > -20.0); // HoldDrop stays what D2 models (opt-in)
    }
}

void TestBoardAnalogOnSplitPath()
{
    std::printf("TestBoardAnalogOnSplitPath\n");
    // Analog RC 4.08 kHz x Sallen-Key 27.7 kHz: -0.05 dB at 438 Hz, -3.03 dB at 4.23 kHz.
    const struct { int fnum, blk; double want; } cases[] = {{580, 4, -0.05}, {700, 7, -3.03}};
    for (const auto& c : cases)
    {
        const double off = RmsFrom(RenderFmSine(RenderMode::HiFi, false, false, c.fnum, c.blk), 4410);
        const double on = RmsFrom(RenderFmSine(RenderMode::HiFi, true, false, c.fnum, c.blk), 4410);
        const double g = 20.0 * std::log10(on / off);
        std::printf("  fnum %d blk %d: board gain %+.2f dB (analog %+.2f)\n", c.fnum, c.blk, g, c.want);
        CHECK(std::fabs(g - c.want) < 0.15);
    }

    // BoardAnalog survives a render-mode / quality change (Configure used to
    // reset it silently).
    const double off = RmsFrom(RenderFmSine(RenderMode::HiFi, false, false, 700, 7, true), 4410);
    const double on = RmsFrom(RenderFmSine(RenderMode::HiFi, true, false, 700, 7, true), 4410);
    const double g = 20.0 * std::log10(on / off);
    std::printf("  board set before SetRenderMode/SetQuality: gain %+.2f dB\n", g);
    CHECK(std::fabs(g + 3.03) < 0.15);
}

// Live output-rate switch (host device renegotiation): every standard rate,
// both modes, split render. Chip state and pending chip-grid audio survive;
// after each switch the renderer delivers rate/50 frames per 20 ms and the
// tone keeps its pitch at the new rate.
void TestLiveOutputRateSwitch()
{
    std::printf("TestLiveOutputRateSwitch\n");
    const double f0 = 580.0 * 16.0 * (static_cast<double>(kMasterClockHz) / kFmDivider) / 1048576.0;
    const uint32_t rates[] = {48000, 88200, 96000, 176400, 192000, 44100};
    for (bool mixed : {false, true})
    for (RenderMode mode : {RenderMode::HiFi, RenderMode::Authentic})
    {
        TestChip tc(2u << 20, 1u << 20, 44100);
        tc.cfg.mode = mode;
        tc.chip.Configure(tc.cfg, &tc.mem);
        tc.chip.EnableSplitStreams(!mixed);
        tc.chip.Reset(0);
        uint64_t t = 10;
        tc.chip.WriteFm(t, 1, 0x05, 0x01);
        const uint8_t w[][2] = {{0x20, 0x21}, {0x23, 0x21}, {0x40, 0x3F}, {0x43, 0x00}, {0x60, 0xF0},
                                {0x63, 0xF0}, {0x80, 0x00}, {0x83, 0x00}, {0xC0, 0x31}, {0xA0, 0x44}, {0xB0, 0x32}};
        for (const auto& x : w)
            tc.chip.WriteFm(t += 10, 0, x[0], x[1]);
        std::vector<float> fm(2 * 8192), pcm(2 * 8192);
        uint64_t clock = 0;
        const uint64_t frameClocks = 882 * kOutClocks; // 20 ms of chip time
        auto runFrames = [&](int frames, uint32_t rate, std::vector<float>* mono) {
            size_t total = 0;
            for (int f = 0; f < frames; f++)
            {
                clock += frameClocks;
                tc.chip.Run(clock);
                const size_t n = mixed ? tc.chip.Render(fm.data(), rate / 50)
                                       : tc.chip.RenderSplit(fm.data(), pcm.data(), rate / 50);
                total += n;
                if (mono)
                    for (size_t i = 0; i < n; i++)
                        mono->push_back(fm[i * 2]);
            }
            return total;
        };
        runFrames(25, 44100, nullptr);
        for (uint32_t rate : rates)
        {
            tc.chip.SetOutputRate(rate);
            CHECK_EQ_I(tc.chip.OutputRate(), rate);
            std::vector<float> mono;
            runFrames(2, rate, nullptr); // settle past the restarted filters
            const size_t total = runFrames(50, rate, &mono);
            const double thd = ThdNdB(mono, 0, f0, static_cast<double>(rate));
            std::printf("  %s %s %6u Hz: %zu frames / 1 s (want %u), 438 Hz tone THD+N %.1f dB\n",
                        mixed ? "Render()     " : "RenderSplit()", mode == RenderMode::HiFi ? "HiFi     " : "Authentic",
                        rate, total, rate, thd);
            CHECK(total + 2 >= rate && total <= rate + 2); // rate/50 per frame: no gaps
            CHECK(thd < (mode == RenderMode::HiFi ? -45.0 : -30.0)); // right pitch at the new rate
        }
    }
}

